#include<bits/stdc++.h>
using namespace std;main(){int n,m,u,v,i,s=0,e;cin>>n>>m;++n;vector<int>G[n],H[n],D(n,0),A[2],P(n,-1),T(n),M(n,0),R(n);while(m--){cin>>u>>v;G[u].push_back(v);H[v].push_back(u);++D[v];}stack<int>S;for(i=1;i<n;++i)if(!D[i])S.push(i);i=1;while(!S.empty()){u=S.top();S.pop();if(P[u]==i)M[i]=M[i-1]+1;P[u]=0;for(int v:H[u])if(R[v]!=i-1&&R[v]+1>=i-1-M[i-1]&&P[T[R[v]+1]])P[u]=R[v];if(!P[u]&&!M[i]){if(s>1){cout<<"NO\n";exit(0);}++s;P[u]=-1;}T[i]=u;R[u]=i++;for(int v:G[u])if(--D[v]==0){S.push(v);P[v]=i;}}s=0;e=n;for(i=n-1;i>0;--i){if(i==e){s^=1;e=P[T[i+1]];}A[s].push_back(T[i]);if(!M[i]){e=P[T[i]];s^=1;}}cout<<"YES\n";for(i=0;i<2;++i){cout<<A[i].size();reverse(A[i].begin(),A[i].end());for(auto e:A[i])cout<<' '<<e;cout<<"\n";}}